// Checkout conversion module - forces conversion tracking and offer logic
const fs = require('fs');
const path = require('path');

const CONVERSION_LOG = path.join(__dirname, '..', '..', 'data', 'conversions.json');

function ensureLog() {
  if (!fs.existsSync(CONVERSION_LOG)) {
    fs.writeFileSync(CONVERSION_LOG, JSON.stringify({ conversions: [], paidEvents: 0 }));
  }
}

function trackConversion(userId, amount, currency = 'USD') {
  ensureLog();
  const data = JSON.parse(fs.readFileSync(CONVERSION_LOG));
  data.conversions.push({ userId, amount, currency, timestamp: new Date().toISOString() });
  data.paidEvents += 1;
  fs.writeFileSync(CONVERSION_LOG, JSON.stringify(data, null, 2));
  return data.paidEvents;
}

function getPaidEvents() {
  ensureLog();
  const data = JSON.parse(fs.readFileSync(CONVERSION_LOG));
  return data.paidEvents;
}

function resetPaidEvents() {
  ensureLog();
  fs.writeFileSync(CONVERSION_LOG, JSON.stringify({ conversions: [], paidEvents: 0 }));
}

module.exports = { trackConversion, getPaidEvents, resetPaidEvents };
